/* Quiz Question Bank — hand-authored MCQs per realm+stage */
(function(){
  window.QUIZ_BANK = [
    {realm:'character',stage:'sprout',lessonId:'char.sp.1',q:'What are the three magic words that open doors?',options:['Please, Thank You, Sorry','Hello, Goodbye, Maybe','Yes, No, Please','Love, Hate, Hope'],correct:0,explanation:'These words show respect and make people want to help you.'},
    {realm:'character',stage:'explorer',lessonId:'char.ex.1',q:'A friend tells you a secret. What is the most respectful thing to do?',options:['Tell another friend for advice','Keep it private and don\'t share','Post about it anonymously online','Wait a week then decide'],correct:1,explanation:'Trust is earned slowly and lost quickly; keeping secrets proves loyalty.'},
    {realm:'character',stage:'teen',lessonId:'char.te.1',q:'Your classmate is being mocked online. What\'s the best first step?',options:['Ignore it — it\'s not your problem','Report the post and tell a trusted adult','Join in so you don\'t get targeted','Confront the bully publicly'],correct:1,explanation:'Reporting and seeking adult support is both safe and effective.'},
    {realm:'character',stage:'teen',lessonId:'char.te.2',q:'A friend pressures you to skip class. What\'s the wisest response?',options:['Go along to keep the friendship','Agree to skip but feel guilty','Politely decline and explain why','Yell at them for being a bad influence'],correct:2,explanation:'A true friend respects your boundaries when you state them clearly.'},
    {realm:'character',stage:'young_adult',lessonId:'char.ya.1',q:'You made a mistake at work that no one noticed. What should you do?',options:['Keep quiet — no harm done','Tell your supervisor and own it','Blame a coworker','Wait to see if someone brings it up'],correct:1,explanation:'Owning mistakes builds trust and shows professional integrity.'},
    {realm:'character',stage:'adult',lessonId:'char.ad.1',q:'What is the most reliable way to build good character over time?',options:['Waiting for the right moment to act','Making grand gestures of kindness','Showing up consistently with small daily choices','Following whatever feels natural'],correct:2,explanation:'Character is built through habits, not one-time events.'},
    {realm:'character',stage:'sage',lessonId:'char.sa.1',q:'Why is forgiveness more for the forgiver than the forgiven?',options:['It makes the forgiver look morally superior','It releases the forgiver from carrying resentment','It ensures the other person feels guilty','It proves you are stronger than them'],correct:1,explanation:'Holding grudges harms the one who holds them far more than the one who caused it.'},
    {realm:'character',stage:'elder',lessonId:'char.el.1',q:'What is the most valuable thing an elder can pass down?',options:['Material wealth and possessions','Stories and lessons from lived experience','Strict rules to follow exactly','Connections to powerful people'],correct:1,explanation:'Wisdom shared through personal experience shapes lives more than any material gift.'},
    {realm:'learning',stage:'sprout',lessonId:'learn.sp.1',q:'When you don\'t understand something, what should you do first?',options:['Pretend you understand to avoid looking silly','Give up and move on','Ask a question or look it up','Wait for someone to explain it to you'],correct:2,explanation:'Asking questions is the fastest path to understanding.'},
    {realm:'learning',stage:'explorer',lessonId:'learn.ex.1',q:'What is "spaced repetition" and why does it help memory?',options:['Studying the same thing over and over in one session','Reviewing material at increasing intervals over days','Only studying when you feel like it','Reading a textbook while listening to music'],correct:1,explanation:'Spacing study sessions helps your brain consolidate memories more effectively.'},
    {realm:'learning',stage:'explorer',lessonId:'learn.ex.2',q:'Which note-taking method helps you understand, not just copy?',options:['Writing every word the teacher says','Using bullet points and rephrasing in your own words','Drawing pictures instead of words','Only writing down things you already know'],correct:1,explanation:'Transforming information into your own words forces deeper processing.'},
    {realm:'learning',stage:'teen',lessonId:'learn.te.3',q:'What does "growth mindset" mean?',options:['You should grow as tall as possible','You can develop intelligence and skills through effort','Only smart people can learn hard things','Talent is fixed at birth'],correct:1,explanation:'Believing you can improve actually makes you more likely to improve.'},
    {realm:'learning',stage:'young_adult',lessonId:'learn.ya.1',q:'What is the Feynman Technique?',options:['A way to make physics easy','Explaining a concept in simple terms to find gaps in your understanding','Memorizing formulas by repeating them','Teaching only advanced students'],correct:1,explanation:'If you can\'t explain it simply, you don\'t understand it well enough.'},
    {realm:'learning',stage:'adult',lessonId:'learn.ad.1',q:'Why is lifelong learning important for adults?',options:['School requires it until age 65','It keeps the brain sharp and opens new opportunities','Employers force you to take courses','Only nerds keep learning after college'],correct:1,explanation:'The brain benefits from continuous challenge at every age.'},
    {realm:'learning',stage:'sage',lessonId:null,q:'What is the paradox of expertise?',options:['Experts know everything','The more you know, the more you realize how much you don\'t know','Experts should stop learning','Beginners learn faster than experts'],correct:1,explanation:'Deep knowledge reveals the vastness of what remains unknown.'},
    {realm:'math',stage:'sprout',lessonId:'math.sp.2',q:'A sunflower head has spirals going both left and right. What do mathematicians call this?',options:['A trick of the eye','A pattern','A coincidence','A mistake in nature'],correct:1,explanation:'Nature is full of mathematical patterns, especially spirals.'},
    {realm:'math',stage:'sprout',lessonId:'math.sp.4',q:'Multiplication is really just fast ______?',options:['Division','Addition','Subtraction','Counting'],correct:1,explanation:'3 × 4 is the same as adding 4 three times: 4+4+4 = 12.'},
    {realm:'math',stage:'explorer',lessonId:'math.ex.1',q:'If something costs $80 and is 25% off, what do you actually pay?',options:['$55','$60','$20','$75'],correct:1,explanation:'25% of $80 is $20, so $80 − $20 = $60.'},
    {realm:'math',stage:'explorer',lessonId:'math.ex.3',q:'A recipe calls for 2 eggs per cup of flour. If you use 3 cups, how many eggs do you need?',options:['3 eggs','4 eggs','5 eggs','6 eggs'],correct:3,explanation:'2 eggs × 3 cups = 6 eggs total.'},
    {realm:'math',stage:'teen',lessonId:'math.te.3',q:'A news headline says "Study finds coffee doubles your risk of X." What should you check first?',options:['How much coffee they measured','The sample size and whether it was correlation or causation','Whether the researcher likes coffee','When the study was published'],correct:1,explanation:'Small studies and correlation alone can create misleading statistics.'},
    {realm:'math',stage:'young_adult',lessonId:'math.ya.1',q:'According to the 50/30/20 budget rule, if you earn $2,500/month after taxes, how much should go to savings?',options:['$250','$500','$750','$1,000'],correct:1,explanation:'20% of $2,500 = $500 for savings and debt repayment.'},
    {realm:'math',stage:'adult',lessonId:'math.ad.2',q:'Using the Rule of 72, if your savings earn 8% interest, approximately how long until your money doubles?',options:['4 years','6 years','9 years','12 years'],correct:2,explanation:'72 ÷ 8 = 9 years for money to double at 8% interest.'},
    {realm:'math',stage:'sage',lessonId:null,q:'Why is compound interest called "the eighth wonder of the world"?',options:['It\'s very complicated','It makes money grow exponentially over time','It was invented in ancient Rome','Only mathematicians understand it'],correct:1,explanation:'Small amounts invested early can grow to enormous sums through compounding.'},
    {realm:'money',stage:'explorer',lessonId:'mon.ex.1',q:'Your friend says "I need this toy." The toy costs $30 and you already have 5 similar toys at home. Is this a want or a need?',options:['Need — you really want it','Want — you don\'t need more toys','Need — toys make you happy','Neither — it\'s a gift'],correct:1,explanation:'Needs are essentials for survival; extra toys are wants.'},
    {realm:'money',stage:'explorer',lessonId:'mon.ex.2',q:'If you get $20 a week allowance and save 25%, how much will you have after 8 weeks?',options:['$20','$40','$60','$160'],correct:1,explanation:'$20 × 0.25 = $5/week. $5 × 8 = $40 total saved.'},
    {realm:'money',stage:'teen',lessonId:'mon.te.1',q:'You earn $15/hour working 10 hours a week. What\'s the best first financial step?',options:['Spend it all while you\'re young','Open a savings account and save at least 20%','Lend it all to friends','Keep it under your mattress'],correct:1,explanation:'Establishing a savings habit early builds lifelong financial discipline.'},
    {realm:'money',stage:'young_adult',lessonId:null,q:'What is the main risk of using a credit card to buy things you can\'t afford?',options:['The store might refuse the card','You pay interest on top of the price, making everything more expensive','The card might get stolen','You\'ll earn fewer reward points'],correct:1,explanation:'Carrying a balance means you pay significantly more than the original price.'},
    {realm:'money',stage:'adult',lessonId:null,q:'What is an emergency fund, and how much should you ideally have?',options:['Money for vacations — 1 month of expenses','Money for unexpected costs — 3 to 6 months of expenses','Money for gifts — $500','Money for investing — your whole paycheck'],correct:1,explanation:'An emergency fund protects you from unexpected expenses without going into debt.'},
    {realm:'money',stage:'sage',lessonId:null,q:'What is the best time to start investing for retirement?',options:['When you get your first high-paying job','In your 40s when you have more money','As early as possible, even with small amounts','Only when your employer offers a match'],correct:2,explanation:'Time in the market matters more than the amount invested, thanks to compounding.'},
    {realm:'money',stage:'elder',lessonId:null,q:'What financial wisdom is most valuable to pass to younger generations?',options:['Which stocks to buy this year','How to avoid debt and build an emergency fund','How to get rich quick','What lottery numbers to pick'],correct:1,explanation:'Foundational financial habits matter more than any specific investment tip.'},
    {realm:'health',stage:'sprout',lessonId:null,q:'How many glasses of water should you drink each day to stay healthy?',options:['1 glass','2 glasses','6 to 8 glasses','No water is needed'],correct:2,explanation:'Water helps your body function properly throughout the day.'},
    {realm:'health',stage:'explorer',lessonId:null,q:'Why is sleep so important for growing bodies?',options:['It\'s just a way to pass time','Your body repairs muscles, grows, and consolidates memories during sleep','Sleep is optional if you eat well','Only babies need lots of sleep'],correct:1,explanation:'Sleep is when your body does most of its physical and mental repair work.'},
    {realm:'health',stage:'teen',lessonId:null,q:'A friend says they skip breakfast to lose weight. What\'s the healthiest response?',options:['That\'s a great idea','Skipping breakfast slows your metabolism and can lead to overeating later','You should skip lunch instead','It doesn\'t matter what you eat'],correct:1,explanation:'Regular meals keep your metabolism active and prevent energy crashes.'},
    {realm:'health',stage:'teen',lessonId:null,q:'What happens to your body when you exercise regularly?',options:['It gets weaker','It becomes more efficient at delivering oxygen and energy','It uses up all your energy permanently','It only helps your muscles, not your heart'],correct:1,explanation:'Regular exercise strengthens your heart, lungs, and muscles while boosting energy.'},
    {realm:'health',stage:'young_adult',lessonId:null,q:'What is the recommended daily screen time limit for adults to protect mental health?',options:['As much as you want','No more than 2 hours of recreational screen time','At least 8 hours','Screen time has no effect on mental health'],correct:1,explanation:'Excessive screen time is linked to anxiety, poor sleep, and reduced focus.'},
    {realm:'health',stage:'adult',lessonId:null,q:'Why is stress management important for long-term health?',options:['It\'s not — stress is always bad','Chronic stress weakens your immune system and increases disease risk','Stress only affects your mood, not your body','Only high-stress jobs need stress management'],correct:1,explanation:'Prolonged stress damages your cardiovascular, immune, and digestive systems.'},
    {realm:'health',stage:'sage',lessonId:null,q:'What is the most effective way to prevent chronic disease as you age?',options:['Taking as many vitamins as possible','Maintaining a balanced diet, regular exercise, and strong social connections','Only focusing on weight loss','Avoiding all doctors'],correct:1,explanation:'Prevention through lifestyle is far more effective than treating disease after it appears.'},
    {realm:'health',stage:'elder',lessonId:null,q:'Why is staying socially active important for elderly health?',options:['It\'s just for entertainment','Social isolation accelerates cognitive decline and increases mortality risk','It doesn\'t really matter','Only extroverts benefit from socializing'],correct:1,explanation:'Strong social connections are as important for longevity as diet and exercise.'},
    {realm:'comm',stage:'explorer',lessonId:null,q:'What is the most important part of being a good listener?',options:['Thinking about what you\'ll say next','Paying full attention and showing you understand','Only listening when you agree','Multitasking while they talk'],correct:1,explanation:'Active listening means giving your full focus to the speaker.'},
    {realm:'comm',stage:'teen',lessonId:null,q:'Your friend is upset and says "I don\'t want to talk about it." What should you do?',options:['Force them to tell you','Respect their space and let them know you\'re there when they\'re ready','Ignore them completely','Tell everyone else about their problem'],correct:1,explanation:'Respecting boundaries while offering support shows emotional maturity.'},
    {realm:'comm',stage:'young_adult',lessonId:null,q:'How should you handle a disagreement with a coworker?',options:['Avoid them forever','Calmly express your perspective, listen to theirs, and look for common ground','Yell louder until they agree','Go to the boss immediately'],correct:1,explanation:'Direct, respectful communication resolves most workplace conflicts.'},
    {realm:'comm',stage:'adult',lessonId:null,q:'What is nonviolent communication (NVC)?',options:['Never arguing about anything','Expressing observations, feelings, needs, and requests without blame','Only speaking when spoken to','Using aggressive language politely'],correct:1,explanation:'NVC focuses on expressing your own experience rather than judging others.'},
    {realm:'comm',stage:'sage',lessonId:null,q:'Why is "the pause" important in difficult conversations?',options:['It shows you don\'t care','It gives you time to choose a thoughtful response instead of reacting','It wastes everyone\'s time','It means you\'re lying'],correct:1,explanation:'Pausing before responding prevents regretful words and allows empathy to arise.'},
    {realm:'comm',stage:'elder',lessonId:null,q:'What is the most powerful gift you can give someone in conversation?',options:['Your opinion on their situation','Your undivided attention and genuine curiosity','A quick solution to their problem','A similar story about yourself'],correct:1,explanation:'Being truly heard is one of the deepest human needs.'},
    {realm:'comm',stage:'young_adult',lessonId:null,q:'How do you give constructive feedback without hurting someone\'s feelings?',options:['Sandwich it between two compliments','Be brutally honest no matter what','Only say positive things','Avoid giving feedback altogether'],correct:0,explanation:'The feedback sandwich (positive-constructive-positive) helps people hear your message.'},
    {realm:'work',stage:'sprout',lessonId:null,q:'What makes a chore feel less like a burden?',options:['Getting paid for it','Doing it with enthusiasm and seeing it as practice for real life','Skipping it entirely','Complaining until someone else does it'],correct:1,explanation:'Chores build responsibility and skills you\'ll need as an adult.'},
    {realm:'work',stage:'explorer',lessonId:null,q:'What is the best way to learn a new skill?',options:['Read about it once and you\'re done','Practice consistently and learn from mistakes','Wait until someone teaches you perfectly','Only do things you\'re already good at'],correct:1,explanation:'Skills come from deliberate practice, not passive learning.'},
    {realm:'work',stage:'teen',lessonId:null,q:'Your first part-time job teaches you more than just the work. What else does it teach?',options:['How to get free stuff','Time management, responsibility, and working with different people','How to avoid your parents','Nothing useful'],correct:1,explanation:'Early jobs build soft skills that are valuable in every career.'},
    {realm:'work',stage:'young_adult',lessonId:null,q:'What is the difference between being busy and being productive?',options:['They\'re the same thing','Being busy means doing many things; being productive means doing the right things','Busy people are lazier','Productive people work longer hours'],correct:1,explanation:'Productivity is about outcomes, not just activity.'},
    {realm:'work',stage:'adult',lessonId:null,q:'Why is "craftsmanship" important even in a digital world?',options:['It\'s outdated and unnecessary','Taking pride in quality work builds reputation and personal satisfaction','Only artisans need craftsmanship','It\'s only important for physical products'],correct:1,explanation:'Craftsmanship means caring about the quality of everything you produce.'},
    {realm:'work',stage:'sage',lessonId:null,q:'What is the relationship between work and meaning?',options:['Work is just for money','Meaningful work comes from contributing to something larger than yourself','Only volunteering can be meaningful','Work and meaning are unrelated'],correct:1,explanation:'The deepest job satisfaction comes from feeling your work matters to others.'},
    {realm:'work',stage:'young_adult',lessonId:null,q:'How do you handle a boss who gives unfair criticism?',options:['Quit immediately','Stay calm, ask for specific examples, and document the feedback','Yell back at them','Ignore everything they say'],correct:1,explanation:'Professional responses to criticism build your reputation and create paper trails.'},
    {realm:'world',stage:'teen',lessonId:null,q:'Why is voting considered both a right and a responsibility?',options:['It\'s required by law everywhere','Your vote is your voice in shaping the society you live in','Only old people should vote','Voting doesn\'t actually change anything'],correct:1,explanation:'Democracy works when citizens participate in choosing their leaders.'},
    {realm:'world',stage:'teen',lessonId:null,q:'How can you tell if a news source is reliable?',options:['If it has lots of ads it must be popular','Check if multiple reputable sources report the same facts','Only trust sources that agree with your opinion','If it\'s on social media it must be true'],correct:1,explanation:'Cross-referencing multiple trusted sources helps verify information.'},
    {realm:'world',stage:'young_adult',lessonId:null,q:'What is cultural humility?',options:['Being quiet in other cultures','Approaching other cultures with respect and willingness to learn','Pretending to understand other cultures','Only respecting your own culture'],correct:1,explanation:'Cultural humility means recognizing you don\'t know everything about other traditions.'},
    {realm:'world',stage:'adult',lessonId:null,q:'Why does civic engagement matter beyond just voting?',options:['It doesn\'t — voting is enough','Community involvement shapes local policies and strengthens democracy','Only politicians need to engage','Civic engagement is only for retired people'],correct:1,explanation:'Attending meetings, volunteering, and speaking up are all vital parts of citizenship.'},
    {realm:'world',stage:'sage',lessonId:null,q:'What does "think globally, act locally" mean?',options:['Ignore global problems','Address big issues through small everyday actions in your community','Only worry about your neighborhood','Move to a bigger city to make a difference'],correct:1,explanation:'Local actions create ripples that affect the wider world.'},
    {realm:'world',stage:'elder',lessonId:null,q:'What is the greatest gift an elder can give to democracy?',options:['Money to political campaigns','Passing down civic values and encouraging younger generations to participate','Staying out of politics','Complaining about how things used to be'],correct:1,explanation:'Elders bridge historical lessons with future civic responsibility.'},
    {realm:'world',stage:'young_adult',lessonId:null,q:'How does media literacy protect you from manipulation?',options:['It doesn\'t — media is always truthful','It helps you identify bias, propaganda, and emotional manipulation in content','It makes you suspicious of everything','Only professionals need media literacy'],correct:1,explanation:'Understanding how media works helps you consume it more wisely.'},
    {realm:'practical',stage:'explorer',lessonId:null,q:'What should you do before you start cooking?',options:['Turn on the oven to maximum','Wash your hands and read the recipe through once','Start chopping without measuring','Leave the kitchen until someone else does it'],correct:1,explanation:'Preparation prevents mistakes and makes cooking safer and easier.'},
    {realm:'practical',stage:'teen',lessonId:null,q:'What is the most important document to keep safe as a teenager?',options:['Your movie ticket stubs','Your birth certificate and Social Security card','Your social media passwords','Your report cards only'],correct:1,explanation:'Identity documents are needed for jobs, school, and legal matters.'},
    {realm:'practical',stage:'young_adult',lessonId:null,q:'Why should you learn basic home repairs?',options:['To impress people','It saves money and prevents small problems from becoming big ones','Only homeowners need to know this','Repairs are always someone else\'s job'],correct:1,explanation:'Fixing small issues early prevents expensive damage later.'},
    {realm:'practical',stage:'young_adult',lessonId:null,q:'What is the best way to organize important digital files?',options:['Save everything to your desktop','Use cloud backup with clear folder naming and regular organization','Never save anything digitally','Only use one device forever'],correct:1,explanation:'A clear digital filing system saves hours and protects against data loss.'},
    {realm:'practical',stage:'adult',lessonId:null,q:'Why is meal planning useful for busy adults?',options:['It\'s a waste of time','It saves money, reduces food waste, and saves decision energy','Only chefs need meal plans','Eating out is always better'],correct:1,explanation:'Planning ahead eliminates the daily stress of "what\'s for dinner?"'},
    {realm:'practical',stage:'sage',lessonId:null,q:'What is the value of learning to sew a button or mend clothes?',options:['It\'s outdated','It extends the life of clothing and builds self-reliance','Only poor people need to know this','It\'s too complicated to learn'],correct:1,explanation:'Basic mending skills save money and reduce waste.'},
    {realm:'practical',stage:'elder',lessonId:null,q:'What practical wisdom should elders pass down about home management?',options:['How to use the latest technology','How to maintain a household with minimal waste and maximum efficiency','Only new methods matter','Home management isn\'t important'],correct:1,explanation:'Time-tested household skills are invaluable for independent living.'},
    {realm:'purpose',stage:'teen',lessonId:null,q:'How do you discover your purpose in life?',options:['Wait for a divine sign','Try many things, notice what energizes you, and reflect on what matters to you','Ask someone else to choose for you','You\'re too young to have a purpose'],correct:1,explanation:'Purpose is often found through exploration and honest self-reflection.'},
    {realm:'purpose',stage:'teen',lessonId:null,q:'What is the difference between a goal and a purpose?',options:['They\'re the same thing','A goal is a specific target; a purpose is the deeper reason behind it','Goals are for adults, purpose is for kids','Purpose is more important than goals'],correct:1,explanation:'Goals are the steps; purpose is the compass that guides them.'},
    {realm:'purpose',stage:'young_adult',lessonId:null,q:'Why is journaling recommended for personal growth?',options:['It\'s a waste of time','It helps you process emotions, clarify thoughts, and track patterns over time','Only writers need to journal','It\'s just a diary for children'],correct:1,explanation:'Writing your thoughts helps you understand yourself more deeply.'},
    {realm:'purpose',stage:'adult',lessonId:null,q:'What does "the examined life" mean?',options:['Checking your health regularly','Reflecting on your values, choices, and meaning on a regular basis','Living perfectly without mistakes','Only philosophers examine life'],correct:1,explanation:'Socrates said the unexamined life is not worth living — self-reflection is essential.'},
    {realm:'purpose',stage:'sage',lessonId:null,q:'What is the relationship between suffering and wisdom?',options:['Suffering should be avoided at all costs','Suffering, when reflected upon, can deepen understanding and compassion','Only weak people suffer','Wisdom comes only from books'],correct:1,explanation:'Many of life\'s deepest lessons come through navigating difficulty with awareness.'},
    {realm:'purpose',stage:'elder',lessonId:null,q:'What is the final wisdom of a life well-lived?',options:['Accumulating as much as possible','Living with love, integrity, and leaving the world slightly better','Fame and recognition','Knowing all the answers'],correct:1,explanation:'The most meaningful lives are defined by contribution, not accumulation.'},
    {realm:'purpose',stage:'adult',lessonId:null,q:'How do you balance ambition with contentment?',options:['Choose one or the other','Stay grateful for what you have while working toward what matters','Never be satisfied — always want more','Stop setting goals after age 30'],correct:1,explanation:'Contentment and growth can coexist when gratitude fuels ambition.'},
    {realm:'art',stage:'sprout',lessonId:null,q:'What colors do you mix to make green?',options:['Red and blue','Yellow and blue','Red and yellow','Black and white'],correct:1,explanation:'Blue and yellow are primary colors that combine to make green.'},
    {realm:'art',stage:'explorer',lessonId:null,q:'Why do artists sometimes break the "rules" of art?',options:['They don\'t know the rules','To express emotion and create something original','Rules don\'t exist in art','Breaking rules is always wrong'],correct:1,explanation:'Art rules are guidelines; breaking them purposefully can create powerful effects.'},
    {realm:'art',stage:'teen',lessonId:null,q:'What is "art criticism" and why is it valuable?',options:['Being mean about artwork','Thoughtfully analyzing and interpreting art to deepen understanding','Only experts can critique art','Art criticism is about finding mistakes'],correct:1,explanation:'Art criticism helps you see deeper layers of meaning in creative work.'},
    {realm:'art',stage:'young_adult',lessonId:null,q:'How does art reflect the society that created it?',options:['Art has nothing to do with society','Art captures the values, struggles, and beauty of its time','Art is always made in isolation','Only modern art reflects society'],correct:1,explanation:'Every era\'s art reveals what that culture cared about most.'},
    {realm:'art',stage:'adult',lessonId:null,q:'Why is visiting museums and galleries important?',options:['It\'s a trendy hobby','It exposes you to different perspectives and develops visual literacy','Only cultured people visit museums','It\'s just looking at old things'],correct:1,explanation:'Encountering art builds empathy and expands how you see the world.'},
    {realm:'art',stage:'sage',lessonId:null,q:'What is the purpose of abstract art?',options:['To confuse people','To express emotions and ideas beyond literal representation','It\'s not real art','Abstract art has no meaning'],correct:1,explanation:'Abstract art communicates through color, form, and energy rather than recognizable images.'},
    {realm:'art',stage:'elder',lessonId:null,q:'Why is it important to preserve art and cultural heritage?',options:['It\'s not important','Art connects us to our past and helps future generations understand history','Only government museums matter','Old art should be replaced with new art'],correct:1,explanation:'Cultural preservation keeps the human story alive for those who come after us.'},
    {realm:'science',stage:'sprout',lessonId:null,q:'What is the first step of the scientific method?',options:['Draw a conclusion','Ask a question','Conduct the experiment','Publish your results'],correct:1,explanation:'Science begins with curiosity — asking a question about something you observe.'},
    {realm:'science',stage:'explorer',lessonId:null,q:'What is a hypothesis?',options:['A proven fact','An educated guess that can be tested','A type of experiment','A scientific tool'],correct:1,explanation:'A hypothesis is a prediction you can test through experimentation.'},
    {realm:'science',stage:'teen',lessonId:null,q:'What is the difference between a theory and a law in science?',options:['Theories are guesses, laws are facts','A law describes what happens; a theory explains why it happens','There is no difference','Laws are always older than theories'],correct:1,explanation:'A scientific law describes patterns; a theory explains the mechanisms behind them.'},
    {realm:'science',stage:'young_adult',lessonId:null,q:'Why is peer review important in science?',options:['It slows down research unnecessarily','Other experts check your work for errors and bias before it\'s published','Only popular scientists get reviewed','Peer review makes research more expensive'],correct:1,explanation:'Peer review catches mistakes and ensures scientific claims are trustworthy.'},
    {realm:'science',stage:'adult',lessonId:null,q:'What does "correlation does not imply causation" mean?',options:['Correlations are always false','Just because two things happen together doesn\'t mean one causes the other','Causation is always provable','Statistics are unreliable'],correct:1,explanation:'Ice cream sales and drowning rates both rise in summer, but one doesn\'t cause the other.'},
    {realm:'science',stage:'sage',lessonId:null,q:'What is the most important quality of a good scientist?',options:['Being the smartest person in the room','Intellectual honesty and willingness to change your mind when evidence demands it','Never making mistakes','Only working alone'],correct:1,explanation:'Science advances when researchers follow evidence, not their egos.'},
    {realm:'science',stage:'elder',lessonId:null,q:'How does scientific literacy protect citizens in a democracy?',options:['It doesn\'t — politics and science are separate','It helps people evaluate evidence and avoid being misled by false claims','Only scientists need scientific literacy','Scientific literacy is only useful for doctors'],correct:1,explanation:'Understanding science helps voters make informed decisions on complex issues.'},
    {realm:'psychology',stage:'explorer',lessonId:null,q:'What is empathy?',options:['Feeling sorry for someone','Understanding and sharing the feelings of another person','Agreeing with everyone','Being too sensitive'],correct:1,explanation:'Empathy is the ability to see the world through another person\'s eyes.'},
    {realm:'psychology',stage:'teen',lessonId:null,q:'What is a cognitive bias?',options:['A type of mental illness','A systematic pattern of deviation from rational thinking','A form of prejudice','Being too logical'],correct:1,explanation:'Cognitive biases are mental shortcuts that can lead to predictable errors in judgment.'},
    {realm:'psychology',stage:'teen',lessonId:null,q:'Why do people sometimes procrastinate even when they know it\'s harmful?',options:['They\'re lazy','It\'s often driven by fear of failure or discomfort, not laziness','They don\'t care about their goals','Procrastination is always voluntary'],correct:1,explanation:'Procrastination is an emotional regulation problem, not a time management problem.'},
    {realm:'psychology',stage:'young_adult',lessonId:null,q:'What is the "bystander effect"?',options:['People are more helpful in emergencies','People are less likely to help when others are present','Bystanders always intervene','Emergency help is always available'],correct:1,explanation:'The more people witness a problem, the less likely any one person is to act.'},
    {realm:'psychology',stage:'adult',lessonId:null,q:'What is the most effective way to change a bad habit?',options:['Use willpower alone','Replace the bad habit with a better one, keeping the same cue and reward','Eliminate all triggers','Just stop doing it'],correct:1,explanation:'Habits are loops of cue-routine-reward; replacing the routine while keeping the cue works best.'},
    {realm:'psychology',stage:'sage',lessonId:null,q:'What does "self-awareness" mean and why does it matter?',options:['Knowing your own personality type','Understanding your own thoughts, emotions, and their effects on others','Being self-centered','Having high self-esteem'],correct:1,explanation:'Self-awareness is the foundation of emotional intelligence and good relationships.'},
    {realm:'psychology',stage:'elder',lessonId:null,q:'What psychological benefit comes from gratitude in later life?',options:['It makes you seem humble','Gratitude reduces anxiety, improves sleep, and increases overall life satisfaction','Gratitude is only for religious people','It doesn\'t have real effects'],correct:1,explanation:'Research shows gratitude practices significantly improve mental and physical health.'},
    {realm:'music',stage:'sprout',lessonId:null,q:'What are the two main parts of every song — the part you sing and the part you clap along to?',options:['The verse and the chorus','The melody and the rhythm','The loud part and the quiet part','The beginning and the end'],correct:1,explanation:'Melody is the tune you sing; rhythm is the beat you feel.'},
    {realm:'music',stage:'explorer',lessonId:null,q:'What makes a drum beat feel groovy?',options:['Playing as fast as possible','Syncopation — accents on unexpected beats','Only using one drum','Playing perfectly on every beat'],correct:1,explanation:'Syncopation creates surprise and excitement in rhythm.'},
    {realm:'music',stage:'teen',lessonId:null,q:'Why does music give you "chills" or goosebumps?',options:['You\'re cold','Unexpected harmonic changes activate the brain\'s reward system','Music is just noise','Only sad songs cause chills'],correct:1,explanation:'Surprise in music triggers dopamine release in the brain.'},
    {realm:'music',stage:'young_adult',lessonId:null,q:'What is "active listening" in music?',options:['Listening while doing other things','Fully focusing on the music to notice layers and details you\'d otherwise miss','Listening only to popular songs','Turning the volume up high'],correct:1,explanation:'Active listening reveals nuances that casual listening misses entirely.'},
    {realm:'music',stage:'adult',lessonId:null,q:'Why is music education valuable even for people who won\'t become musicians?',options:['It isn\'t — music is only for performers','It develops discipline, emotional expression, and neural connections that benefit all areas of life','It\'s just a fun hobby','Only talented children need music education'],correct:1,explanation:'Music training enhances memory, math skills, and emotional intelligence.'},
    {realm:'music',stage:'sage',lessonId:null,q:'What is the connection between music and memory?',options:['There is no connection','Music activates more brain regions than almost any other activity and can unlock distant memories','Music makes you forget things','Only classical music affects memory'],correct:1,explanation:'Music is deeply tied to the hippocampus, the brain\'s memory center.'},
    {realm:'music',stage:'elder',lessonId:null,q:'Why does music from your youth remain powerful decades later?',options:['It doesn\'t — you just feel nostalgic','Music becomes encoded with emotional memories during formative years','Old music is objectively better','The brain stops encoding new musical memories'],correct:1,explanation:'Adolescent musical memories are encoded with peak emotional intensity during brain development.'},
    {realm:'film',stage:'explorer',lessonId:null,q:'What is a "protagonist"?',options:['The bad guy','The main character the story follows','The narrator','Any character in the story'],correct:1,explanation:'The protagonist is the central character whose journey drives the story.'},
    {realm:'film',stage:'teen',lessonId:null,q:'What does a close-up shot tell you that a wide shot doesn\'t?',options:['Where the character is','The character\'s emotions and inner thoughts through their facial expression','How big the set is','How many people are in the scene'],correct:1,explanation:'Close-ups create intimacy by showing subtle emotional details.'},
    {realm:'film',stage:'teen',lessonId:null,q:'What is the "hero\'s journey" in storytelling?',options:['A story about traveling','A universal pattern where a hero leaves home, faces challenges, and returns transformed','A documentary format','Any story with a happy ending'],correct:1,explanation:'The hero\'s journey appears across cultures and centuries as a fundamental narrative pattern.'},
    {realm:'film',stage:'young_adult',lessonId:null,q:'What makes a documentary different from fiction film?',options:['Documentaries are always better','Documentaries present real events and people rather than invented stories','Documentaries don\'t have directors','Fiction films are never based on real events'],correct:1,explanation:'Documentaries aim to represent reality, though they still make creative choices.'},
    {realm:'film',stage:'adult',lessonId:null,q:'Why is "show, don\'t tell" important in visual storytelling?',options:['It\'s just a cliché','Visuals communicate emotion and information more powerfully than dialogue alone','Audiences prefer silence','It makes films shorter'],correct:1,explanation:'Cinema is a visual medium; what you see often matters more than what you hear.'},
    {realm:'film',stage:'sage',lessonId:null,q:'What role does film play in shaping cultural memory?',options:['None — entertainment is separate from history','Films preserve perspectives and emotions of eras that books and photos cannot capture','Only historical dramas matter','Film is purely commercial'],correct:1,explanation:'Film captures not just what happened, but what it felt like to live through it.'},
    {realm:'film',stage:'elder',lessonId:null,q:'Why is sharing stories across generations important?',options:['It isn\'t — each generation should create new stories','Stories carry values, lessons, and emotional connections that bind families and communities','Only written stories matter','Old stories are outdated'],correct:1,explanation:'Storytelling is the oldest form of teaching and the strongest form of human connection.'},
    {realm:'design',stage:'explorer',lessonId:null,q:'What is "white space" in design and why is it important?',options:['The color white in paintings','Empty areas that give elements room to breathe and guide the eye','A mistake in the layout','Areas that haven\'t been designed yet'],correct:1,explanation:'White space creates visual clarity and prevents overwhelming the viewer.'},
    {realm:'design',stage:'teen',lessonId:null,q:'What is the "rule of thirds" in visual composition?',options:['Divide everything into thirds of the same color','Place key elements at intersection points of a 3×3 grid for more dynamic composition','Use exactly three colors in every design','Only use three fonts'],correct:1,explanation:'The rule of thirds creates more balanced, engaging compositions than centering everything.'},
    {realm:'design',stage:'teen',lessonId:null,q:'Why do some colors feel "warm" and others feel "cool"?',options:['It\'s just a cultural habit','Warm colors (red, orange, yellow) are associated with fire and sun; cool colors with water and sky','Colors have actual temperature','It depends on the screen brightness'],correct:1,explanation:'Color psychology is rooted in natural associations our brains have learned over millennia.'},
    {realm:'design',stage:'young_adult',lessonId:null,q:'What is "user-centered design"?',options:['Designing for what the designer likes','Designing with the end user\'s needs, abilities, and experiences as the primary focus','Making things look trendy','Designing by committee'],correct:1,explanation:'Good design solves problems for real people, not just looks beautiful.'},
    {realm:'design',stage:'adult',lessonId:null,q:'Why is typography more than just choosing a font?',options:['It doesn\'t matter — all fonts are the same','Typography affects readability, mood, and how people perceive your message','Only graphic designers need to know about typography','Typography is only important for printed materials'],correct:1,explanation:'The right typeface can make your message feel trustworthy, playful, or urgent.'},
    {realm:'design',stage:'sage',lessonId:null,q:'What is the relationship between simplicity and elegance in design?',options:['Simple designs are boring','The most elegant designs solve complex problems with apparent ease','Elegance requires complexity','Simplicity and elegance are opposites'],correct:1,explanation:'True design elegance makes difficult things feel effortless and intuitive.'},
    {realm:'design',stage:'elder',lessonId:null,q:'How has the role of design changed over the decades?',options:['Design hasn\'t changed at all','Design has moved from purely decorative to being central to how we interact with technology and information','Design used to be more important','Design is only for new products'],correct:1,explanation:'From industrial objects to digital interfaces, design now shapes nearly every human interaction.'},
    {realm:'literature',stage:'sprout',lessonId:null,q:'What is a "fable"?',options:['A true story','A short story that teaches a moral lesson, often with talking animals','A long scientific book','A type of poem'],correct:1,explanation:'Fables like Aesop\'s use simple stories to teach timeless lessons.'},
    {realm:'literature',stage:'explorer',lessonId:null,q:'What is a "metaphor" and why do writers use them?',options:['A type of joke','A comparison that doesn\'t use "like" or "as" to create vivid imagery','A long description','A factual statement'],correct:1,explanation:'Metaphors make writing more vivid by comparing two unlike things directly.'},
    {realm:'literature',stage:'teen',lessonId:null,q:'Why is reading fiction important for developing empathy?',options:['It isn\'t — fiction is just entertainment','Fiction lets you live inside another person\'s mind and understand their perspective','Fiction stories are always realistic','Only non-fiction teaches truth'],correct:1,explanation:'Research shows reading fiction increases your ability to understand others\' feelings and thoughts.'},
    {realm:'literature',stage:'young_adult',lessonId:null,q:'What makes a poem different from prose?',options:['Poems are always shorter','Poetry uses line breaks, rhythm, and concentrated language to create meaning beyond the words','Poetry is easier to write','Prose never uses literary devices'],correct:1,explanation:'Poetry packs more meaning into fewer words through deliberate structure and sound.'},
    {realm:'literature',stage:'adult',lessonId:null,q:'Why do classic novels remain relevant across centuries?',options:['People are forced to read them','They explore universal human themes that transcend their original time period','Classics are always better written','They\'re shorter than modern books'],correct:1,explanation:'Works like Shakespeare and Austen endure because they illuminate timeless human truths.'},
    {realm:'literature',stage:'sage',lessonId:null,q:'What is the relationship between literature and wisdom?',options:['Literature is just entertainment','Literature explores the deepest questions of human existence through narrative and metaphor','Wisdom only comes from non-fiction','Literature is too subjective to teach wisdom'],correct:1,explanation:'Great literature grapples with the same questions philosophers ask, but through lived experience.'},
    {realm:'literature',stage:'elder',lessonId:null,q:'Why should elders share the books and poems that shaped them?',options:['They shouldn\'t — taste changes','Sharing literature creates intergenerational bonds and preserves the emotional wisdom of past eras','Young people only want new books','Literature loses value over time'],correct:1,explanation:'A book recommended by someone who loved it decades ago carries deeper meaning than any algorithm.'},
    { realm:'comm', stage:'teen', lessonId:null, q:'What does Gottman call a small bid for connection?', options:['A love map','A small bid for connection','A repair attempt','A turning point'], correct:1, explanation:'Gottman calls small everyday bids for connection the foundation of relationships.' },
    { realm:'comm', stage:'young_adult', lessonId:null, q:'In Gottman\'s research, what ratio predicts relationship success?', options:['3:1','5:1','1:1','7:1'], correct:1, explanation:'The magic ratio is 5 positive interactions for every 1 negative one.' },
    { realm:'comm', stage:'young_adult', lessonId:null, q:'What are Gottman\'s Four Horsemen?', options:['Stonewalling, criticism, defensiveness, contempt','Anger, jealousy, fear, resentment','Avoidance, passive-aggression, manipulation, dishonesty','Lying, cheating, stealing,背叛'], correct:0, explanation:'The Four Horsemen are stonewalling, criticism, defensiveness, and contempt.' },
    { realm:'comm', stage:'adult', lessonId:null, q:'What is a "love map"?', options:['A map to your partner\'s favorite places','A detailed mental map of your partner\'s inner world','A relationship timeline','A shared travel journal'], correct:1, explanation:'A love map is your knowledge of your partner\'s dreams, fears, and inner life.' },
    { realm:'psychology', stage:'teen', lessonId:null, q:'What does "active constructive responding" mean?', options:['Giving advice during a conversation','Responding to good news with enthusiasm and support','Actively ignoring negative comments','Constructing arguments in a debate'], correct:1, explanation:'It means responding to good news with genuine enthusiasm and active engagement.' },
    { realm:'psychology', stage:'teen', lessonId:null, q:'What is self-compassion?', options:['Being selfish and putting yourself first','Treating yourself with kindness during difficult times','Ignoring your mistakes','Rewarding yourself after success'], correct:1, explanation:'Self-compassion is treating yourself with the same kindness you would offer a friend.' },
    { realm:'psychology', stage:'teen', lessonId:null, q:'What is learned optimism?', options:['Pretending everything is fine all the time','Choosing to interpret setbacks as temporary and specific','Being naturally positive','Ignoring negative emotions'], correct:1, explanation:'Learned optimism is the skill of reframing negative events as temporary and changeable.' },
    { realm:'psychology', stage:'young_adult', lessonId:null, q:'What is the hedonic treadmill?', options:['Exercising to improve your mood','Returning to a baseline happiness level after life changes','Running until you feel joy','Chasing happiness through shopping'], correct:1, explanation:'The hedonic treadmill is the tendency to return to a stable happiness level after good or bad events.' },
    { realm:'psychology', stage:'young_adult', lessonId:null, q:'What is flow?', options:['Moving water in nature','A state of deep focus where time seems to disappear','The feeling after meditation','Going with the crowd'], correct:1, explanation:'Flow is a state of complete immersion in an activity where time and self-awareness fade.' },
    { realm:'money', stage:'young_adult', lessonId:null, q:'What is lifestyle creep?', options:['Gradually spending more as your income rises','A slow-growing investment account','Rising food costs over time','Inflation affecting rent prices'], correct:0, explanation:'Lifestyle creep is when your spending increases as you earn more, often without realizing it.' },
    { realm:'money', stage:'adult', lessonId:null, q:'What is prosocial spending?', options:['Spending money on social media','Spending money on others or charitable causes','Spending money to fit in with peers','Spending money on group activities'], correct:1, explanation:'Prosocial spending is using your money to benefit others, which research links to greater happiness.' },
    { realm:'world', stage:'teen', lessonId:null, q:'What is phishing?', options:['A way to catch fish for food','Fraudulent messages trying to steal personal information','A type of internet speed test','Online shopping from home'], correct:1, explanation:'Phishing is a scam where attackers pose as trusted sources to trick you into sharing sensitive data.' },
    { realm:'world', stage:'young_adult', lessonId:null, q:'What is a digital footprint?', options:['The size of your hard drive','The trail of data you leave online through your activity','A computer virus','Your online shopping history only'], correct:1, explanation:'A digital footprint is the record of all your online activities and the data you leave behind.' },
    { realm:'health', stage:'teen', lessonId:null, q:'Why are vapes addictive?', options:['Because they contain nicotine which rewires the brain\'s reward system','Because the flavors are habit-forming','Because they look cool','Because they cost a lot of money'], correct:0, explanation:'Vapes contain nicotine, which is highly addictive and can disrupt adolescent brain development.' },
    { realm:'practical', stage:'sprout', lessonId:null, q:'When should you ask for help?', options:['Only when adults are watching','Whenever you feel stuck, unsafe, or overwhelmed','Never, you should figure it out alone','Only during school hours'], correct:1, explanation:'Asking for help is a strength, not a weakness, especially when you feel stuck or unsafe.' },
    { realm:'world', stage:'elder', lessonId:null, q:'How do you recognize the grandparent scam?', options:['They ask for your bank password','They pressure you to send money quickly while pretending to be a relative in trouble','They ask for your social security number over the phone','They offer you a free vacation'], correct:1, explanation:'The grandparent scam involves someone pretending to be a grandchild in urgent trouble, pressuring you to send money fast.' },
    {realm:'travel',stage:'sprout',lessonId:null,q:'Why is learning "hello" in different languages important?',options:['It makes you sound smart','It shows respect and opens doors to new friendships','It\'s just a fun trick','Languages are all the same'],correct:1,explanation:'Greeting someone in their own language shows you care about their culture and identity.'},
    {realm:'travel',stage:'explorer',lessonId:null,q:'What do people everywhere have in common?',options:['Nothing — cultures are completely different','We all wake up, eat, work, play, and share meals with people we love','Everyone speaks the same language','Food is the same everywhere'],correct:1,explanation:'Despite different customs, the rhythms of daily human life are remarkably similar everywhere.'},
    {realm:'travel',stage:'teen',lessonId:null,q:'Why is "culture shock" actually good for you?',options:['It isn\'t — it\'s just unpleasant','Discomfort rewires your brain and builds empathy, patience, and adaptability','It means you should go home','Only weak people feel culture shock'],correct:1,explanation:'Feeling out of place forces your brain to adapt, which is the foundation of personal growth.'},
    {realm:'travel',stage:'young_adult',lessonId:null,q:'How does being a foreigner change you?',options:['It doesn\'t — you stay the same person','You become a wider version of yourself with new rhythms, tastes, and understanding','You become a better version','You lose your original identity'],correct:1,explanation:'Living abroad doesn\'t replace who you are — it expands who you can become.'},
    {realm:'travel',stage:'adult',lessonId:null,q:'Why does travel help recalibrate your perspective?',options:['It doesn\'t — it\'s just a vacation','Seeing how others live makes your own problems feel smaller and your life feel bigger','Travel makes you forget your problems','Other people\'s lives are always better'],correct:1,explanation:'Travel gives you distance from your own world, which reveals what truly matters.'},
    {realm:'travel',stage:'sage',lessonId:null,q:'What is the greatest gift you can give a child through travel?',options:['Expensive souvenirs','A world bigger than their backyard and the confidence to navigate it','Perfect photos','Famous landmarks'],correct:1,explanation:'Showing children the world teaches them adaptability, curiosity, and that life is vast.'},
    {realm:'travel',stage:'elder',lessonId:null,q:'Why are travel memories so precious as we age?',options:['They aren\'t — they fade like everything else','They prove you lived wide, not just long, and they become richer with telling','Only current experiences matter','Memories make you sad'],correct:1,explanation:'Travel memories carry sensory richness that deepens over time, connecting you to your fullest life.'}
  ];
})();
